from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[2]

def package(title, tasks, accept, dependencies, review=None):
    return dict(title=title, tasks=tasks, accept=accept, dependencies=dependencies, review=review)

def sprint(code, title, phase, goal, prereq, scope, architecture, tests, demo, risks, packages):
    return dict(code=code, title=title, phase=phase, goal=goal, prereq=prereq, scope=scope,
                architecture=architecture, tests=tests, demo=demo, risks=risks, packages=packages)

def load_initial():
    text = ROOT/'docs/candidat/02_SPRINTS_CINQ_DEVELOPPEURS.md'
    data = text.read_text(encoding='utf-8')
    result=[]
    blocks=re.split(r'^## \d+\. Sprint (S\d) — (.+)$',data,flags=re.M)
    for i in range(1,len(blocks),3):
        code,title,body=blocks[i:i+3]
        body=body.split('\n## ')[0]
        goal=re.search(r'\*\*Objectif :\*\* (.+?) \*\*Démonstration :\*\*',body).group(1).strip()
        demo=re.search(r'\*\*Démonstration :\*\* (.+)',body).group(1).strip()
        pk=[]
        pblocks=re.split(r'^### S\d-D\d — (.+)$',body,flags=re.M)
        for j in range(1,len(pblocks),2):
            pt,pbody=pblocks[j:j+2]
            lines=re.findall(r'^- (.+)$',pbody,flags=re.M)
            tasks=[v for v in lines if not v.startswith(('Réception :','Dépendance :'))]
            accept=next(v[12:] for v in lines if v.startswith('Réception :'))
            dep=next(v[13:] for v in lines if v.startswith('Dépendance :'))
            pk.append(package(pt,tasks,accept,dep))
        assert len(pk)==5,(code,len(pk))
        c=CORE[code]
        result.append(sprint(code,title,'Socle candidat texte',goal,c['prereq'],c['scope'],c['architecture'],c['tests'],demo,c['risks'],pk))
    return result

